# Mock the necessary classes and functions to test the logic
class MockArgs:
    def __init__(self):
        self.package_query = "compiler=clang"  # This should prevent recipe removal
        self.confirm = True
        self.dry_run = True

class MockPackageList:
    def __init__(self):
        self.refs_data = {
            ("zlib", "1.2.13"): {
                "packages": None  # No packages match the query
            }
        }
        self.recipes = {
            "zlib/1.2.13": {
                "revisions": {
                    "13c96f538b52e1600c40b88994de240f": {}
                }
            }
        }

    def refs(self):
        return self.refs_data

class MockRef:
    def __init__(self, name, version):
        self.name = name
        self.version = version
        self.revision = "13c96f538b52e1600c40b88994de240f"

    def repr_notime(self):
        return f"{self.name}/{self.version}#{self.revision}"

# Test the fixed logic
def test_remove_logic():
    args = MockArgs()
    package_list = MockPackageList()

    # Simulate the fixed logic
    for ref_bundle in package_list.refs().values():
