    print("Testing fixed logic:")
    fixed_result = test_remove_logic()

    print("\nTesting original (buggy) logic:")
    original_result = test_original_logic()

    print(f"\nFixed logic works correctly: {fixed_result}")
    print(f"Original logic has bug: {not original_result}")
